    ECHO 势(Shi) 技术架构 - 三维编织与64卦约束

        @layer base {
            body {
                font-family: 'Noto Serif SC', serif;
                background: #050508;
                color: #e5e5e5;
                overflow-x: hidden;
            }
            .font-mono {
                font-family: 'JetBrains Mono', monospace;
            }
        }
        @layer components {
            .gradient-text {
                background: linear-gradient(135deg, #4A7C6F 0%, #8B9D83 30%, #C4A77D 60%, #8B7EB8 100%);
                -webkit-background-clip: text;
                -webkit-text-fill-color: transparent;
                background-clip: text;
            }
            .glow-border {
                box-shadow: 0 0 30px rgba(74, 124, 111, 0.2), inset 0 0 30px rgba(74, 124, 111, 0.05);
            }
            .glow-text {
                text-shadow: 0 0 20px rgba(74, 124, 111, 0.5);
            }
            .hexagram-grid {
                display: grid;
                grid-template-columns: repeat(4, 1fr);
                gap: 6px;
            }
            /* Enhanced Slider Styles */
            .slider-container {
                position: relative;
                padding: 20px 0 30px;
            }
            .slider-track {
                position: relative;
                height: 4px;
                background: linear-gradient(90deg, #1a1a2e 0%, #2d2d44 50%, #1a1a2e 100%);
                border-radius: 2px;
            }
            .slider-marks {
                position: absolute;
                top: -6px;
                left: 0;
                right: 0;
                height: 16px;
                display: flex;
                justify-content: space-between;
                padding: 0 8px;
            }
            .slider-mark {
                width: 2px;
                height: 8px;
                background: #6a6a7e;
                border-radius: 1px;
            }
            .slider-mark.active {
                background: #4A7C6F;
                height: 12px;
            }
            .dimension-slider {
                -webkit-appearance: none;
                width: 100%;
                height: 4px;
                background: transparent;
                outline: none;
                position: absolute;
                top: 0;
                left: 0;
                margin: 0;
            }
            .dimension-slider::-webkit-slider-thumb {
                -webkit-appearance: none;
                appearance: none;
                width: 24px;
                height: 24px;
                border-radius: 50%;
                background: linear-gradient(135deg, #4A7C6F, #5B8A7A);
                cursor: pointer;
                box-shadow: 0 0 20px rgba(74, 124, 111, 0.6), inset 0 0 0 3px #050508;
                border: 2px solid #4A7C6F;
                transition: all 0.2s ease;
                margin-top: -10px;
            }
            .dimension-slider::-webkit-slider-thumb:hover {
                transform: scale(1.15);
                box-shadow: 0 0 30px rgba(74, 124, 111, 0.8), inset 0 0 0 3px #050508;
            }
            .dimension-slider::-webkit-slider-runnable-track {
                height: 4px;
                background: transparent;
            }
            .slider-labels {
                display: flex;
                justify-content: space-between;
                margin-top: 12px;
                padding: 0 4px;
            }
            .slider-label {
                font-size: 11px;
                color: #9a9aae;
                text-align: center;
                flex: 1;
                transition: color 0.3s;
            }
            .slider-label.active {
                color: #4A7C6F;
                font-weight: 500;
            }
            .yao-line {
                height: 5px;
                margin: 10px 0;
                border-radius: 3px;
                transition: all 0.4s ease;
            }
            .yao-yang {
                background: linear-gradient(90deg, #4A7C6F, #8B9D83, #4A7C6F);
                background-size: 200% 100%;
                animation: shimmer 3s infinite;
                width: 100%;
            }
            .yao-yin {
                background: transparent;
                width: 100%;
                position: relative;
            }
            .yao-yin::before,
            .yao-yin::after {
                content: '';
                position: absolute;
                height: 100%;
                width: 42%;
                background: linear-gradient(90deg, #3a3a4e, #4a4a5e);
                border-radius: 3px;
            }
            .yao-yin::after {
                right: 0;
            }
            @keyframes shimmer {
                0% { background-position: -200% 0; }
                100% { background-position: 200% 0; }
            }
            .code-block {
                background: linear-gradient(135deg, #0a0a12, #12121a);
                border: 1px solid #1f1f2e;
                border-radius: 12px;
                padding: 1.5rem;
                overflow-x: auto;
            }
            .nav-item {
                transition: all 0.3s ease;
                position: relative;
            }
            .nav-item::before {
                content: '';
                position: absolute;
                left: 0;
                top: 0;
                bottom: 0;
                width: 3px;
                background: linear-gradient(180deg, #4A7C6F, #8B7EB8);
                opacity: 0;
                transition: opacity 0.3s;
            }
            .nav-item:hover {
                background: rgba(74, 124, 111, 0.1);
            }
            .nav-item:hover::before {
                opacity: 1;
            }
            .nav-item.active {
                background: rgba(74, 124, 111, 0.15);
            }
            .nav-item.active::before {
                opacity: 1;
            }
            .tensor-cell {
                aspect-ratio: 1;
                display: flex;
                align-items: center;
                justify-content: center;
                font-size: 0.7rem;
                border-radius: 6px;
                cursor: pointer;
                transition: all 0.3s ease;
                border: 1px solid #2a2a3e;
            }
            .tensor-cell:hover {
                transform: scale(1.15);
                z-index: 10;
                box-shadow: 0 0 20px rgba(74, 124, 111, 0.4);
            }
            .flow-line {
                position: relative;
            }

